        ow += kx;
        int npx = (!g_mdu.sw_lethal && g_npcwXMove == move
                   && g_npcwX > 0) ? g_npcwX : 0;
        g_npcwXMove = 0;      // The swing's own wind-up (see wup_ct)
        if (npx)
            ow = npx;
